"""Generate pure token C ABI constants from the canonical contract."""
import argparse
import json
import pprint
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    spec = json.loads((ROOT / 'contracts/native_token_count_abi_v1.json').read_text())
    lines = [
        '//! @generated by scripts/gen_native_token_count_abi.py; do not edit.',
        f"pub const ABI_VERSION: u32 = {spec['abi_version']};",
    ]
    for group in ('encodings', 'status'):
        prefix = 'ENCODING' if group == 'encodings' else 'STATUS'
        for key, value in spec[group].items():
            lines.append(f'pub const {prefix}_{key}: u32 = {value};')
    raw = '\n'.join(lines) + '\n'
    target = ROOT / 'packages/tofu-runtime/src/generated_token_count_abi.rs'
    outputs = {
        target: raw,
        ROOT / 'lib/agent_core/native_token_count_contract.py':
            '"""Generated from native_token_count_abi_v1.json; do not edit."""\n'
            + 'TOKEN_COUNT_SPEC = ' + pprint.pformat(spec, sort_dicts=False, width=100) + '\n',
    }
    for path, content in outputs.items():
        if args.check:
            if not path.exists() or path.read_text() != content:
                raise SystemExit(f'token ABI constants differ: {path.name}; regenerate')
        else:
            path.write_text(content)


if __name__ == '__main__':
    main()
